/bin/bash -lc "node --input-type=module <<'EOF'
const base = 'http://localhost:3100'
const cases = [
  ['home', '/', 200, ['Welcome to My Blog', 'Home - My Blog', 'Your user agent:']],
  ['blog', '/blog', 200, ['All Blog Posts', 'Blog - My Blog']],
  ['post 1', '/blog/1', 200, ['Comments (5)', '← Back']],
  ['post 11', '/blog/11', 200, ['Comments (5)']],
  ['missing post', '/blog/9999', 404, ['404 - Page Not Found']],
  ['missing route', '/absent', 404, ['404 - Page Not Found']],
]
for (const [name, path, status, fragments] of cases) {
  const response = await fetch(base + path)
  const body = await response.text()
  const missing = fragments.filter((fragment) => "'!body.includes(fragment))
  if (response.status !== status || missing.length) {
    throw new Error(`${name}: got ${response.status}, missing ${missing.join('"', ')}"'`)
  }
  console.log(`${name}: ${response.status}`)
}
const requests = [
  ['"'list', '/api/posts', { method: 'GET' }, 200, (body) => Array.isArray(body) && body.length === 2],
  ['create', '/api/posts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: 'New', content: 'Text' }) }, 201, (body) => body.title === 'New'],
  ['invalid create', '/api/posts', { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: '{}' }, 400, (body) => body.error === 'Title and content are required'],
  ['get one', '/api/posts/7', { method: 'GET' }, 200, (body) => body.id === 7],
  ['update', '/api/posts/7', { method: 'PUT', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ title: 'Updated', content: 'Body' }) }, 200, (body) => body.title === 'Updated'],
  ['delete', '/api/posts/7', { method: 'DELETE' }, 200, (body) => body.message === 'Post 7 deleted successfully'],
]
for (const [name, path, options, status, check] of requests) {
  const response = await fetch(base + path, options)
  const body = await response.json()
  if (response.status "'!== status || !check(body)) {
    throw new Error(`${name}: got ${response.status} ${JSON.stringify(body)}`)
  }
  console.log(`${name}: ${response.status}`)
}
const unsupported = await fetch(base + '"'/api/posts', { method: 'PATCH' })
if (unsupported.status "'!== 405) throw new Error(`unsupported method: ${unsupported.status}`)
console.log(`unsupported method: ${unsupported.status}`)
EOF'

